package nl.smartstreamlabs.sbwdroneconfig;
import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.*;import net.minecraft.resources.ResourceLocation;import org.joml.Matrix4f;import org.joml.Matrix3f;import org.joml.Vector3f;import software.bernie.geckolib.cache.object.*;import software.bernie.geckolib.model.GeoModel;import software.bernie.geckolib.util.RenderUtils;import java.util.*;

/** Immutable assembly preview of an existing Geo model. No entity, animatable
 * session or world insertion. Never changes bones shared with live vehicles. */
public final class DwfStaticGeo{
 private record Key(ResourceLocation model,ResourceLocation texture){}
 private record Part(GeoCube cube,Matrix4f pose,int stage){}
 private static final Map<Key,DwfStaticGeo>CACHE=new HashMap<>();
 private final ResourceLocation texture;private final List<Part>parts=new ArrayList<>();private final BakedGeoModel flat;private GeoCube rigid;
 private float minX=Float.POSITIVE_INFINITY,minY=minX,minZ=minX,maxX=Float.NEGATIVE_INFINITY,maxY=maxX,maxZ=maxX;
 public static DwfStaticGeo get(GeoModel<?> provider){var model=provider.getModelResource(null);var texture=provider.getTextureResource(null);return CACHE.computeIfAbsent(new Key(model,texture),k->new DwfStaticGeo(provider.getBakedModel(model),texture));}
 public static DwfStaticGeo get(ResourceLocation model,ResourceLocation texture){return CACHE.computeIfAbsent(new Key(model,texture),key->{var provider=new GeoModel<software.bernie.geckolib.core.animatable.GeoAnimatable>(){public ResourceLocation getModelResource(software.bernie.geckolib.core.animatable.GeoAnimatable ignored){return model;}public ResourceLocation getTextureResource(software.bernie.geckolib.core.animatable.GeoAnimatable ignored){return texture;}public ResourceLocation getAnimationResource(software.bernie.geckolib.core.animatable.GeoAnimatable ignored){return model;}};return new DwfStaticGeo(provider.getBakedModel(model),texture);});}
 /** Original custom mesh resources used by FL-01/NDC-01, without an entity. */
 public static DwfStaticGeo binary(ResourceLocation metadata,ResourceLocation binary,ResourceLocation texture){return CACHE.computeIfAbsent(new Key(metadata,texture),key->{var resources=net.minecraft.client.Minecraft.getInstance().getResourceManager();try(var reader=new java.io.InputStreamReader(resources.getResourceOrThrow(metadata).open(),java.nio.charset.StandardCharsets.UTF_8);var in=new java.io.DataInputStream(new java.io.BufferedInputStream(resources.getResourceOrThrow(binary).open()))){var json=com.google.gson.JsonParser.parseReader(reader).getAsJsonObject();var descriptions=json.getAsJsonArray("bones");if(in.readInt()!=0x464c3031||in.readInt()!=descriptions.size())throw new java.io.IOException("Invalid original assembly mesh");var poses=new Matrix4f[descriptions.size()];var groups=new ArrayList<GeoBone>();for(int part=0;part<descriptions.size();part++){var desc=descriptions.get(part).getAsJsonObject();int parent=desc.get("parent").getAsInt();var pivot=desc.getAsJsonArray("pivot");var rotation=desc.getAsJsonArray("rotation");float x=pivot.get(0).getAsFloat(),y=pivot.get(1).getAsFloat(),z=pivot.get(2).getAsFloat();var matrix=poses[part]=parent<0?new Matrix4f():new Matrix4f(poses[parent]);matrix.translate(x,y,z).rotateZYX((float)Math.toRadians(rotation.get(2).getAsDouble()),(float)Math.toRadians(rotation.get(1).getAsDouble()),(float)Math.toRadians(rotation.get(0).getAsDouble())).translate(-x,-y,-z);int count=in.readInt();if(count<0||count>50000)throw new java.io.IOException("Invalid original mesh face count");var quads=new GeoQuad[count];var normals=new Matrix3f(matrix);for(int f=0;f<count;f++){var normal=normals.transform(new Vector3f(in.readFloat(),in.readFloat(),in.readFloat())).normalize();var vertices=new GeoVertex[4];for(int n=0;n<4;n++){var point=matrix.transformPosition(new Vector3f(in.readFloat(),in.readFloat(),in.readFloat()));vertices[n]=new GeoVertex(point.x,point.y,point.z).withUVs(in.readFloat(),in.readFloat());}quads[f]=new GeoQuad(vertices,normal,net.minecraft.core.Direction.getNearest(normal.x,normal.y,normal.z));}if(count>0){var cube=new GeoCube(quads,net.minecraft.world.phys.Vec3.ZERO,net.minecraft.world.phys.Vec3.ZERO,new net.minecraft.world.phys.Vec3(1,1,1),0,false);MeshRenderData.register(cube);var bone=new GeoBone(null,desc.get("name").getAsString(),false,0d,false,false);bone.getCubes().add(cube);groups.add(bone);}}if(in.read()!=-1)throw new java.io.IOException("Trailing original mesh data");return new DwfStaticGeo(new BakedGeoModel(groups,null),texture);}catch(java.io.IOException failure){throw new IllegalStateException("Cannot load assembly preview "+metadata,failure);}});}
 public static void clear(){for(var value:CACHE.values()){Adv01Gpu.release(value.flat);DwfStaticGpu.release(value.rigid);}CACHE.clear();}
 private DwfStaticGeo(BakedGeoModel source,ResourceLocation texture){this.texture=texture;var groups=new ArrayList<GeoBone>();var poses=new PoseStack();for(var bone:source.topLevelBones())collect(bone,poses,groups,0);flat=new BakedGeoModel(groups,null);freeze();}
 private void collect(GeoBone source,PoseStack p,List<GeoBone>groups,int parentStage){
  int stage=Math.max(parentStage,stage(source.getName()));
  p.pushPose();var rest=source.getInitialSnapshot();var poseBone=new GeoBone(null,source.getName(),false,0d,false,false);poseBone.setPivotX(source.getPivotX());poseBone.setPivotY(source.getPivotY());poseBone.setPivotZ(source.getPivotZ());
  poseBone.setRotX(rest==null?source.getRotX():rest.getRotX());poseBone.setRotY(rest==null?source.getRotY():rest.getRotY());poseBone.setRotZ(rest==null?source.getRotZ():rest.getRotZ());poseBone.setPosX(rest==null?source.getPosX():rest.getOffsetX());poseBone.setPosY(rest==null?source.getPosY():rest.getOffsetY());poseBone.setPosZ(rest==null?source.getPosZ():rest.getOffsetZ());poseBone.setScaleX(rest==null?source.getScaleX():rest.getScaleX());poseBone.setScaleY(rest==null?source.getScaleY():rest.getScaleY());poseBone.setScaleZ(rest==null?source.getScaleZ():rest.getScaleZ());RenderUtils.prepMatrixForBone(p,poseBone);
  if(!source.getCubes().isEmpty()){var group=new GeoBone(null,source.getName(),false,0d,false,false);for(var cube:source.getCubes()){
   if(MeshRenderData.get(cube)==null)MeshRenderData.register(cube);parts.add(new Part(cube,new Matrix4f(p.last().pose()),stage));group.getCubes().add(cube);p.pushPose();RenderUtils.translateToPivotPoint(p,cube);RenderUtils.rotateMatrixAroundCube(p,cube);RenderUtils.translateAwayFromPivotPoint(p,cube);
   for(var quad:cube.quads())if(quad!=null)for(var v:quad.vertices()){var point=p.last().pose().transformPosition(new Vector3f(v.position()));minX=Math.min(minX,point.x);minY=Math.min(minY,point.y);minZ=Math.min(minZ,point.z);maxX=Math.max(maxX,point.x);maxY=Math.max(maxY,point.y);maxZ=Math.max(maxZ,point.z);}p.popPose();
  }groups.add(group);}
  for(var child:source.getChildBones())collect(child,p,groups,stage);p.popPose();
 }
 private static int stage(String bone){String name=bone.toLowerCase(java.util.Locale.ROOT);if(name.matches(".*(antenna|hatch|door|wire|cable|panel|marking).*"))return 3;if(name.matches(".*(camera|sensor|optic|turret|barrel|gun|scope|mast|payload).*"))return 2;if(name.matches(".*(wheel|track|tread|wing|propeller|leg|motor|suspension).*"))return 1;return 0;}
 private void freeze(){var faces=new ArrayList<GeoQuad>();var flips=new java.io.ByteArrayOutputStream();var stages=new java.io.ByteArrayOutputStream();for(var part:parts){var local=new PoseStack();local.last().pose().set(part.pose());local.last().normal().set(new Matrix3f(part.pose()));RenderUtils.translateToPivotPoint(local,part.cube());RenderUtils.rotateMatrixAroundCube(local,part.cube());RenderUtils.translateAwayFromPivotPoint(local,part.cube());var data=MeshRenderData.get(part.cube());int flags=(data.flipX?1:0)|(data.flipY?2:0)|(data.flipZ?4:0);for(var quad:part.cube().quads())if(quad!=null){var normal=local.last().normal().transform(new Vector3f(quad.normal())).normalize();var vertices=new GeoVertex[4];for(int n=0;n<4;n++){var v=quad.vertices()[n];var point=local.last().pose().transformPosition(new Vector3f(v.position()));vertices[n]=new GeoVertex(point.x,point.y,point.z).withUVs(v.texU(),v.texV());}faces.add(new GeoQuad(vertices,normal,net.minecraft.core.Direction.getNearest(normal.x,normal.y,normal.z)));flips.write(flags);stages.write(part.stage());}}rigid=new GeoCube(faces.toArray(GeoQuad[]::new),net.minecraft.world.phys.Vec3.ZERO,net.minecraft.world.phys.Vec3.ZERO,new net.minecraft.world.phys.Vec3(1,1,1),0,false);MeshRenderData.register(rigid);DwfStaticGpu.metadata(rigid,flips.toByteArray(),stages.toByteArray());}
 public void draw(PoseStack p,MultiBufferSource buffers,int light,int overlay){draw(p,buffers,light,overlay,3);}
 public void draw(PoseStack p,MultiBufferSource buffers,int light,int overlay,int stage){
  if(parts.isEmpty())return;p.pushPose();float scale=Math.min(3f/Math.max(.01f,maxX-minX),Math.min(1.9f/Math.max(.01f,maxY-minY),3f/Math.max(.01f,maxZ-minZ)));p.scale(scale,scale,scale);p.translate(-(minX+maxX)/2,-minY,-(minZ+maxZ)/2);
  var type=RenderType.entityCutoutNoCull(texture);if(buffers instanceof MultiBufferSource.BufferSource&&DwfStaticGpu.draw(rigid,type,p,light,overlay,stage)){p.popPose();return;}var batch=buffers instanceof MultiBufferSource.BufferSource?Adv01Gpu.batchGrouped(flat):null;if(batch!=null)batch.begin();
  for(var part:parts){if(part.stage()>stage)continue;p.pushPose();p.last().pose().mul(part.pose());p.last().normal().mul(new Matrix3f(part.pose()));if(batch!=null)batch.pose(part.cube(),p);else{RenderUtils.translateToPivotPoint(p,part.cube());RenderUtils.rotateMatrixAroundCube(p,part.cube());RenderUtils.translateAwayFromPivotPoint(p,part.cube());emit(p,buffers.getBuffer(type),MeshRenderData.get(part.cube()),light,overlay);}p.popPose();}
  if(batch!=null)batch.draw(type,light,overlay,1,1,1,1);p.popPose();
 }
 private static void emit(PoseStack p,VertexConsumer out,MeshRenderData data,int light,int overlay){
  if(MeshBulkWriter.draw(out,data,p.last().pose(),p.last().normal(),light,overlay,1,1,1,1))return;var m=p.last().pose();var n=p.last().normal();var values=data.values;
  for(int at=0;at<values.length;at+=23){float nx=n.m00()*values[at]+n.m10()*values[at+1]+n.m20()*values[at+2],ny=n.m01()*values[at]+n.m11()*values[at+1]+n.m21()*values[at+2],nz=n.m02()*values[at]+n.m12()*values[at+1]+n.m22()*values[at+2];for(int i=at+3;i<at+23;i+=5){float x=values[i],y=values[i+1],z=values[i+2];out.vertex(m.m00()*x+m.m10()*y+m.m20()*z+m.m30(),m.m01()*x+m.m11()*y+m.m21()*z+m.m31(),m.m02()*x+m.m12()*y+m.m22()*z+m.m32(),1,1,1,1,values[i+3],values[i+4],overlay,light,nx,ny,nz);}}
 }
}
